public boolean validateWrite()
{
    boolean ret = next validateWrite();
    boolean usedForPriceTree = GUPParameters::attributeGroupUsedForPriceTree(EcoResAttributeGroup::find(this.AttributeGroup));

    if (usedForPriceTree)
    {
        warning("@GlobalUnifiedPricing:SalesOrderAttributeGroupUsedForPriceTree");
        return false;
    }

    return ret;
}

public boolean validateDelete()
{
    boolean ret = next validateDelete();
    boolean usedForPriceTree = GUPParameters::attributeGroupUsedForPriceTree(EcoResAttributeGroup::find(this.AttributeGroup));

    if (usedForPriceTree)
    {
        warning("@GlobalUnifiedPricing:SalesOrderAttributeGroupUsedForPriceTree");
        return false;
    }

    return ret;
}
